-- 거짓말하는 테스트

@Test
@Transactional
void 통과하는데_거짓말() {
    Member m = memberRepository.save(new Member("김", 20));
    Member found = memberRepository.findById(m.getId()).orElseThrow();
    assertThat(found.getUsername()).isEqualTo("김");
    System.out.println("--- 테스트 끝 ---");
}

--- 테스트 끝 ---
INFO  Rolled back transaction for test

--   SQL 이 하나도 안 나갔다
--   insert 도 select 도 없다
--   전부 1차 캐시에서 답했다
--   DB 는 이 회원을 본 적이 없다


-- flush 를 넣으면

@Test
@Transactional
void flush_넣기() {
    Member m = memberRepository.save(new Member("김", 20));
    em.flush();
    System.out.println("--- flush 후 ---");
    Member found = memberRepository.findById(m.getId()).orElseThrow();
    System.out.println("조회: " + found.getUsername());
}

