-- clear 뒤에는 준영속이다

@Test
@Transactional
void 준영속() {
    Team t = new Team("A팀"); em.persist(t);
    Member m = new Member("김", 20, t);
    memberRepository.save(m);
    em.flush();
    em.clear();

    System.out.println("--- clear 했다 ---");
    System.out.println("영속 상태: " + em.contains(m));
    m.getTeam().getName();
}

