-- 준영속은 변경 감지도 안 된다

@Test
@Transactional
void 변경_감지_안_됨() {
    Member m = memberRepository.save(new Member("김", 20));
    em.flush(); em.clear();

    m.changeAge(99);          // 준영속 객체를 고쳤다
    em.flush();
    System.out.println("--- flush 했다 ---");

    Member found = memberRepository.findById(m.getId()).orElseThrow();
    System.out.println("나이: " + found.getAge());
}

